1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface QuoteStep {
11	  op: "quote";
12	  items: {
13	    type: KnownItemType;
14	    material?: string;
15	    enchantment?: number;
16	    cursed?: boolean;
17	  }[];
18	}
19	
20	export type Step = QuoteStep;
21	
22	export interface ScenarioResults {
23	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
24	}
25	
26	const PROCESSING_FEE = 5;
27	const BASE_PREMIUM_BY_TYPE = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	  moonstone: 25,
34	} as const satisfies Record<string, number>;
35	
36	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
37	const FIRST_INSURANCE_SURCHARGE = 0.1;
38	
39	// Percentage arithmetic leaves values like 71.00000000000001, which would
40	// otherwise round up to 72. Settle the float noise before rounding.
41	const FLOAT_NOISE_DIGITS = 6;
42	const withoutFloatNoise = (amount: number): number =>
43	  Number(amount.toFixed(FLOAT_NOISE_DIGITS));
44	
45	const roundUpInFavourOfMHPCO = (amount: number): number =>
46	  Math.ceil(withoutFloatNoise(amount));
47	
48	type Item = QuoteStep["items"][number];
49	
50	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
51	
52	const BLOCK_SIZE = 3;
53	const BLOCK_BASE_PREMIUM = 60;
54	
55	const groupByType = (items: Item[]): Item[][] => {
56	  const groups = new Map<KnownItemType, Item[]>();
57	  for (const item of items) {
58	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
59	  }
60	  return [...groups.values()];
61	};
62	
63	const sumOfBasePremiums = (items: Item[]): number =>
64	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
65	
66	// Exactly three alike components form a block at a reduced premium; any
67	// other count is priced per item.
68	//
69	// Deliberate simplification: "component" is not yet enforced, so three alike
70	// swords would also get the block. No test covers it and the spec gives no
71	// example — revisit when one does.
72	const groupBasePremiumOf = (group: Item[]): number =>
73	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
74	
75	const policyBasePremiumOf = (items: Item[]): number =>
76	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
77	
78	const CURSE_SURCHARGE = 0.5;
79	
80	// Item-specific modifiers are charged as a percentage of the affected item's
81	// OWN base premium. See withPolicyWideModifiers for the other scope.
82	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
83	  basePremiumOf(item) * rate;
84	
85	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
86	const HIGH_ENCHANTMENT_THRESHOLD = 5;
87	
88	const isHighlyEnchanted = (item: Item): boolean =>
89	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
90	
91	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
92	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
93	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
94	];
95	
96	// Every modifier rate in this domain combines additively, whether item-scoped
97	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
98	const combinedRate = (rates: number[]): number =>
99	  rates.reduce((total, rate) => total + rate, 0);
100	
101	// Both item modifiers can apply at once, and they stack additively: a cursed
102	// item with enchantment 5 pays 50 % + 30 % of its base premium.
103	const surchargeRateOn = (item: Item): number =>
104	  combinedRate(
105	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
106	      ({ rate }) => rate,
107	    ),
108	  );
109	
110	const surchargeOn = (item: Item): number =>
111	  shareOfOwnBasePremium(item, surchargeRateOn(item));
112	
113	const itemSurchargesOf = (items: Item[]): number =>
114	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
115	
116	// Policy-wide modifiers scale the whole policy base premium, unlike item
117	// modifiers which are charged against the affected item's own base premium.
118	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
119	// its base — not 110 % × 80 %.
120	const LOYALTY_DISCOUNT = -0.2;
121	const LOYALTY_THRESHOLD_YEARS = 2;
122	
123	const isLoyal = (customer: Customer): boolean =>
124	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
125	
126	const policyWideModifierRatesFor = (customer: Customer): number[] => [
127	  FIRST_INSURANCE_SURCHARGE,
128	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
129	];
130	
131	const withPolicyWideModifiers = (
132	  policyBase: number,
133	  customer: Customer,
134	): number =>
135	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(customer)));
136	
137	const quotePremium = ({ items }: QuoteStep, customer: Customer): number =>
138	  roundUpInFavourOfMHPCO(
139	    withPolicyWideModifiers(policyBasePremiumOf(items), customer) +
140	      itemSurchargesOf(items) +
141	      PROCESSING_FEE,
142	  );
143	
144	export const runScenario = (scenario: Scenario): ScenarioResults => ({
145	  results: scenario.steps.map((step) => ({
146	    premium: quotePremium(step, scenario.customer),
147	  })),
148	});
